mapper.select:
SELECT ${groupExpr} AS bucket,
       COUNT(*) AS rowCount,
       COALESCE(SUM(amount), 0) AS totalAmount
FROM electronic_receipt
WHERE deleted = 0
  AND tenant_id = #{tenantId}

    AND account_no = #{accountNo}


    AND issue_time >= #{startTime}


    AND issue_time < #{endTime}

GROUP BY ${groupExpr}
ORDER BY bucket
LIMIT #{limit}
